        return switch (nivel) {
            case "PRATA" -> subtotalProdutos.multiply(BigDecimal.valueOf(0.02))
                    .setScale(2, RoundingMode.HALF_EVEN);
            case "OURO" -> subtotalProdutos.multiply(BigDecimal.valueOf(0.05))
                    .setScale(2, RoundingMode.HALF_EVEN);
            default -> BigDecimal.ZERO.setScale(2);
        };
    }
}

